<script setup lang="ts">
import { computed, onMounted, ref, watch, onUnmounted } from 'vue'
import { useI18n } from 'vue-i18n'
import { api, money, number, percent, json } from '../api'
import { channels, type ProductSummary } from '../types'
import { useApp } from '../stores/app'
import Icon from '../components/Icon.vue'
import ExportDialog from '../components/ExportDialog.vue'
const { t } = useI18n(); const app = useApp(); const products = ref<ProductSummary[]>([]); const allProducts = ref<ProductSummary[]>([]); const loading = ref(true); const selected = ref<string[]>([]); const showExport = ref(false)
const filters = ref({ search: '', category: '', channel: '', verdict: '', archived: 'false', sort: 'updated', direction: 'desc' }); let timer: ReturnType<typeof setTimeout> | undefined; let request = 0
const stats = computed(() => ({ total: allProducts.value.length, promising: allProducts.value.filter(p => ['healthy','viable'].includes(p.headline.verdict)).length, needsWork: allProducts.value.filter(p => ['thin','unprofitable'].includes(p.headline.verdict)).length, categories: new Set(allProducts.value.map(p => p.input.category)).size }))
const hasFilters = computed(() => Object.entries(filters.value).some(([k,v]) => ['search','category','channel','verdict'].includes(k) && v))
async function load() { const token = ++request; loading.value = true; try { const data = await api<{items: ProductSummary[]}>(`/products?${new URLSearchParams(filters.value)}`); if (token === request) { products.value = data.items; selected.value = selected.value.filter(id => data.items.some(p => p.id === id)) } } catch (e) { app.report(e) } finally { if (token === request) loading.value = false } }
async function loadStats() { try { allProducts.value = (await api<{items: ProductSummary[]}>('/products')).items } catch (e) { app.report(e) } }
watch(filters, () => { clearTimeout(timer); timer = setTimeout(load, 250) }, { deep: true }); onMounted(() => { load(); loadStats() }); onUnmounted(() => clearTimeout(timer))
function toggleAll(event: Event) { selected.value = (event.target as HTMLInputElement).checked ? products.value.map(p => p.id) : [] }
function reset() { filters.value.search = ''; filters.value.category = ''; filters.value.channel = ''; filters.value.verdict = '' }
async function archive(p: ProductSummary) { app.clear(); try { await api(`/products/${p.id}/${p.archived ? 'restore' : 'archive'}`, json('POST', { version: p.version })); app.success(t(p.archived ? 'restoredSuccess' : 'archivedSuccess')); await Promise.all([load(), loadStats()]) } catch (e) { app.report(e) } }
const initial = (name: string) => name.split(/\s+/).slice(0,2).map(s => s.charAt(0).toUpperCase()).join('')
</script>
<template>
 <section class="page-heading"><div><span class="eyebrow"><span class="eyebrow-line"></span>{{ t('fresh') }}</span><h1>{{ t('pageTitle') }}</h1><p>{{ t('pageSub') }}</p></div><RouterLink to="/research" class="btn primary"><Icon name="plus" />{{ t('newProduct') }}</RouterLink></section>
 <div class="stat-grid"><div class="stat-card"><span class="stat-icon neutral"><Icon name="box" /></span><div><span>{{ t('total') }}</span><strong>{{ number(stats.total) }}</strong></div><span class="stat-decoration">↗</span></div><div class="stat-card"><span class="stat-icon green"><Icon name="trend" /></span><div><span>{{ t('promising') }}</span><strong>{{ number(stats.promising) }}<small>{{ stats.total ? Math.round(stats.promising / stats.total * 100) : 0 }}%</small></strong></div></div><div class="stat-card"><span class="stat-icon amber"><Icon name="research" /></span><div><span>{{ t('needsWork') }}</span><strong>{{ number(stats.needsWork) }}</strong></div></div><div class="stat-card"><span class="stat-icon purple"><Icon name="layers" /></span><div><span>{{ t('categoriesCount') }}</span><strong>{{ stats.categories }}<small>/ {{ app.categories.length }}</small></strong></div></div></div>
 <section class="panel evaluation-panel"><div class="panel-heading"><div class="heading-inline"><h2>{{ t('saved') }}</h2><span class="count-pill">{{ products.length }}</span></div><div class="panel-actions"><button class="btn secondary compact" :disabled="products.length === 0" @click="showExport = true"><Icon name="download" :size="16" />{{ t('export') }}<span v-if="selected.length">({{ selected.length }})</span></button></div></div>
 <div class="list-toolbar"><div class="search-input"><Icon name="search" :size="18" /><input v-model="filters.search" :placeholder="t('search')" :aria-label="t('search')" /></div><select v-model="filters.category" :aria-label="t('category')"><option value="">{{ t('allCategories') }}</option><option v-for="c in app.categories" :key="c" :value="c">{{ t(c) }}</option></select><select v-model="filters.channel" :aria-label="t('channel')"><option value="">{{ t('allChannels') }}</option><option v-for="c in channels" :key="c" :value="c">{{ t(c) }}</option></select><select v-model="filters.verdict" :aria-label="t('verdict')"><option value="">{{ t('allVerdicts') }}</option><option v-for="c in ['healthy','viable','thin','unprofitable']" :key="c" :value="c">{{ t(c) }}</option></select></div>
 <div class="list-subtoolbar"><div class="segment-control"><button :class="{ chosen: filters.archived === 'false' }" @click="filters.archived = 'false'">{{ t('active') }}</button><button :class="{ chosen: filters.archived === 'true' }" @click="filters.archived = 'true'">{{ t('archived') }}</button><button :class="{ chosen: filters.archived === 'all' }" @click="filters.archived = 'all'">{{ t('all') }}</button></div><div class="sort-controls"><span v-if="selected.length" class="muted">{{ selected.length }} {{ t('selected') }}</span><select v-model="filters.sort" :aria-label="t('updated')"><option value="updated">{{ t('updated') }}</option><option value="created">{{ t('created') }}</option><option value="margin">{{ t('margin') }}</option><option value="profit">{{ t('profit') }}</option></select><button class="icon-btn" :aria-label="t(filters.direction === 'desc' ? 'ascending' : 'descending')" @click="filters.direction = filters.direction === 'desc' ? 'asc' : 'desc'"><Icon name="arrowUp" :class="{ rotate: filters.direction === 'desc' }" :size="16" /></button></div></div>
 <div v-if="loading" class="loading-state"><span class="spinner"></span>{{ t('loading') }}</div>
 <div v-else-if="products.length" class="table-wrap"><table class="product-table"><thead><tr><th class="check-cell"><input type="checkbox" :checked="selected.length === products.length && products.length > 0" :aria-label="t('selectAll')" @change="toggleAll" /></th><th>{{ t('product') }}</th><th>{{ t('evaluatedPrice') }}<small>{{ t('cost') }}</small></th><th>{{ t('orders') }}</th><th>{{ t('channel') }}</th><th>{{ t('margin') }}<small>{{ t('profit') }}</small></th><th>{{ t('verdict') }}</th><th></th></tr></thead><tbody><tr v-for="(p, index) in products" :key="p.id"><td><input v-model="selected" type="checkbox" :value="p.id" :aria-label="`${t('product')} ${p.input.name}`" /></td><td><RouterLink :to="`/products/${p.id}`" class="product-cell"><span class="product-avatar" :class="`color-${index % 5}`">{{ initial(p.input.name) }}</span><span><strong>{{ p.input.name }}</strong><small>{{ p.input.sku || '—' }}<span class="dot-separator">·</span>{{ t(p.input.category) }}<span v-if="p.archived"> · {{ t('archived') }}</span></small></span></RouterLink></td><td class="numeric"><strong>{{ money(p.headline.price) }}</strong><small>{{ money(p.input.cost) }}</small></td><td class="numeric">{{ number(p.input.orders) }}</td><td><span class="channel-label"><i :class="`channel-${p.evaluation.recommended}`"></i>{{ t(p.evaluation.recommended) }}</span></td><td class="numeric"><strong :class="Number(p.headline.margin) < 0 ? 'negative' : 'positive'">{{ percent(p.headline.margin) }}</strong><small>{{ money(p.headline.monthlyProfit) }}</small></td><td><span class="badge" :class="p.headline.verdict"><i></i>{{ t(p.headline.verdict) }}</span></td><td><div class="row-actions"><button class="icon-btn" :aria-label="t(p.archived ? 'restore' : 'archive')" :title="t(p.archived ? 'restore' : 'archive')" @click="archive(p)"><Icon :name="p.archived ? 'refresh' : 'archive'" :size="17" /></button><RouterLink :to="`/products/${p.id}`" class="icon-btn" :aria-label="p.input.name"><Icon name="chevron" :size="17" /></RouterLink></div></td></tr></tbody></table></div>
 <div v-else class="empty-state"><div class="empty-illustration"><div class="illustration-ring"></div><div class="illustration-card"><span></span><span></span><span></span><div class="illustration-chart"><i></i><i></i><i></i><i></i><i></i></div></div><span class="illustration-check"><Icon name="check" /></span><span class="illustration-spark">✦</span></div><h3>{{ hasFilters ? t('noResults') : t('emptyTitle') }}</h3><p v-if="!hasFilters">{{ t('emptyText') }}</p><button v-if="hasFilters" class="btn secondary" @click="reset">{{ t('clearFilters') }}</button><RouterLink v-else to="/research" class="btn primary"><Icon name="plus" />{{ t('newProduct') }}</RouterLink></div>
 <div class="table-footer"><span><Icon name="info" :size="15" />{{ t('independent') }}</span><span>{{ products.length }} {{ t('products').toLowerCase() }}</span></div></section>
 <div class="bottom-banner"><div class="banner-symbol"><Icon name="calculator" :size="26" /></div><div><strong>{{ t('researchTitle') }}</strong><p>{{ t('researchSub') }}</p></div><RouterLink to="/research" class="text-link">{{ t('newProduct') }}<Icon name="arrow" :size="18" /></RouterLink></div>
 <ExportDialog v-if="showExport" :ids="selected" :filters="filters" @close="showExport = false" />
</template>
